from __future__ import annotations
import math
from collections import defaultdict
from itertools import combinations
from shapely.geometry import LineString, Point
from shapely.ops import polygonize, unary_union
from ..cad.model import CadDocument,CadLine,CadPolyline
from .model import TopologyEdge,TopologyFace,TopologyGraph,TopologyNode

class TopologyEngine:
    def __init__(self,*,tolerance_m:float=1e-4,gap_tolerance_m:float=.02): self.tol=tolerance_m; self.gap_tol=gap_tolerance_m
    def _segments(self,doc):
        out=[]
        for e in doc.entities:
            if isinstance(e,CadLine): out.append((e.id,e.layer,(e.start.x,e.start.y),(e.end.x,e.end.y)))
            elif isinstance(e,CadPolyline):
                pts=[(p.x,p.y) for p in e.points]; pairs=list(zip(pts,pts[1:]))
                if e.closed and pts and pts[0]!=pts[-1]: pairs.append((pts[-1],pts[0]))
                out += [(f'{e.id}:{i}',e.layer,a,b) for i,(a,b) in enumerate(pairs)]
        return [s for s in out if math.dist(s[2],s[3])>self.tol]
    def _key(self,p): return (round(p[0]/self.tol),round(p[1]/self.tol))
    def build(self,document:CadDocument,*,repair_gaps:bool=True)->TopologyGraph:
        raw=self._segments(document); cuts={sid:{a,b} for sid,_,a,b in raw}; lines={sid:LineString([a,b]) for sid,_,a,b in raw}
        for A,B in combinations(raw,2):
            sa,sb=A[0],B[0]; inter=lines[sa].intersection(lines[sb]); pts=[]
            if inter.geom_type=='Point': pts=[(inter.x,inter.y)]
            elif inter.geom_type=='MultiPoint': pts=[(p.x,p.y) for p in inter.geoms]
            elif inter.geom_type in {'LineString','MultiLineString'}:
                b=inter.boundary
                if b.geom_type=='MultiPoint': pts=[(p.x,p.y) for p in b.geoms]
            for p in pts: cuts[sa].add(p); cuts[sb].add(p)
        coords={}; sources=defaultdict(set); edges=[]; ec=0
        def nid(p):
            k=self._key(p); coords.setdefault(k,(float(p[0]),float(p[1]))); return f'N_{k[0]}_{k[1]}'
        for sid,layer,a,b in raw:
            line=lines[sid]; pts=sorted(cuts[sid],key=lambda p:line.project(Point(p)))
            for p in pts: sources[nid(p)].add(sid.split(':')[0])
            for p,q in zip(pts,pts[1:]):
                if math.dist(p,q)<=self.tol: continue
                ec+=1; edges.append(TopologyEdge(id=f'E{ec:05d}',start_node_id=nid(p),end_node_id=nid(q),source_entity_id=sid.split(':')[0],layer=layer,length=math.dist(p,q)))
        def coord_from_id(node_id): return next(v for k,v in coords.items() if f'N_{k[0]}_{k[1]}'==node_id)
        if repair_gaps:
            degree=defaultdict(int)
            for e in edges: degree[e.start_node_id]+=1; degree[e.end_node_id]+=1
            ends=[n for n in sources if degree[n]==1]; used=set()
            for a,b in combinations(ends,2):
                if a in used or b in used: continue
                d=math.dist(coord_from_id(a),coord_from_id(b))
                if self.tol<d<=self.gap_tol:
                    ec+=1; edges.append(TopologyEdge(id=f'E{ec:05d}',start_node_id=a,end_node_id=b,source_entity_id='__gap_repair__',layer='__synthetic__',length=d,synthetic=True)); used|={a,b}
        degree=defaultdict(int)
        for e in edges: degree[e.start_node_id]+=1; degree[e.end_node_id]+=1
        nodes=[]
        for k,xy in sorted(coords.items()):
            n=f'N_{k[0]}_{k[1]}'; d=degree[n]; kind='endpoint' if d<=1 else 'pass' if d==2 else 't_junction' if d==3 else 'cross' if d==4 else 'junction'
            nodes.append(TopologyNode(id=n,x=xy[0],y=xy[1],degree=d,kind=kind,source_entity_ids=sorted(sources[n])))
        by={n.id:n for n in nodes}; gl=[]
        for e in edges:
            a,b=by[e.start_node_id],by[e.end_node_id]; gl.append(LineString([(a.x,a.y),(b.x,b.y)]))
        faces=[]
        if gl:
            for i,p in enumerate(polygonize(unary_union(gl)),1):
                if p.area<=self.tol*self.tol: continue
                src=[e.source_entity_id for e,g in zip(edges,gl) if p.boundary.intersection(g).length>self.tol and not e.synthetic]
                faces.append(TopologyFace(id=f'F{i:04d}',boundary=[(float(x),float(y)) for x,y in list(p.exterior.coords)[:-1]],area=float(p.area),source_entity_ids=sorted(set(src))))
        faces.sort(key=lambda f:(round(f.area,9),f.id))
        return TopologyGraph(nodes=nodes,edges=edges,faces=faces,metadata={'tolerance_m':self.tol,'gap_tolerance_m':self.gap_tol,'gaps_repaired':sum(e.synthetic for e in edges)})
